class Course:
    def __init__(self, code, credits):
        self.code = code
        self.credits = credits

class Enrollment:
    def __init__(self, course_code, grade_points):
        self.course_code = course_code
        self._grade_points = grade_points
    def get_grade_points(self):
        return self._grade_points

class University:
    def __init__(self):
        self.courses = {}  # course_code: Course
        self.students = {}  # student_id: List[Enrollment]
    def add_course(self, course):
        self.courses[course.code] = course
    def enroll_student(self, student_id, enrollment):
        self.students.setdefault(student_id, []).append(enrollment)
    def get_student_enrollments(self, student_id):
        return self.students.get(student_id, [])
    def get_course(self, course_code):
        return self.courses.get(course_code)

# The function signature given:
def calculate_simple_gpa(university, student_id):
    '''
    See prompt.
    '''
    total_points = 0.0
    total_credits = 0.0
    enrollments = university.get_student_enrollments(student_id)
    for enrollment in enrollments:
        course = university.get_course(enrollment.course_code)
        if not course:
            continue
        grade_points = enrollment.get_grade_points()
        total_points += grade_points * course.credits
        total_credits += course.credits
    if total_credits == 0:
