        self.reorder_point = reorder_point

class Warehouse:
    def __init__(self, products, stock_by_sku):
        self._products = products
        self._stock_by_sku = stock_by_sku

    def get_all_products(self):
        return self._products

    def get_current_stock(self, sku):
        return self._stock_by_sku.get(sku, 0)

# Fake function for the purpose of assertions only!
def inventory_low_stock_alert(warehouse):
    result = []
    for product in warehouse.get_all_products():
        current_stock = warehouse.get_current_stock(product.sku)
        if current_stock < product.reorder_point:
            result.append({
                'sku': product.sku,
                'name': product.name,
                'current_stock': current_stock,
                'reorder_point': product.reorder_point,
                'deficit': product.reorder_point - current_stock
            })
    return result

