from typing import Optional, Dict, Any, Union

def performance_report(employee_id: Optional[str] = None, report_type: str = 'summary'
                     ) -> Union[Dict[str, Any], Dict[str, Dict[str, Any]]]:
    '''
    Create a performance_report function that reads performance_reviews.csv from PROJECT KNOWLEDGE. Parameters: employee_id (optional string), report_type (string, default 'summary').
    RETURN TYPES AND FIELD SPECIFICATIONS:
      (1) summary mode - find CSV row where employee_id column matches parameter, return single dict with keys 'employee_id' (string value), 'overall_rating' (float from CSV column - keep as float not string), 'goals_status' (string from CSV column).
      (2) detailed mode - find matching row, return single dict with ALL CSV column names as keys preserving exact names and original types.
      (3) department mode - when employee_id is None, group rows by 'department' CSV column, return dict where keys are department names and values are dicts with 'avg_rating' (float - average of overall_rating column) and 'count' (int - number of employees).
    '''
    # -- Step 1: Read CSV
    rows = []
    with open('performance_reviews.csv', newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for line in reader:
            # convert numeric fields
            parsed = dict(line)
            for field in [
                'technical_score', 'communication_score', 'teamwork_score',
                'leadership_score', 'overall_rating'
            ]:
                if field in parsed:
                    # If blank, treat as 0.0
                    try:
                        parsed[field] = float(parsed[field])
                    except Exception:
                        parsed[field] = 0.0
            rows.append(parsed)

    # -- Step 2: Mode handling
    if report_type == 'summary' and employee_id:
        for r in rows:
            if r['employee_id'] == employee_id:
                return {
                    'employee_id': r['employee_id'],
                    'overall_rating': r['overall_rating'],
                    'goals_status': r['goals_status']
                }
        return {}  # Not found

    elif report_type == 'detailed' and employee_id:
        for r in rows:
            if r['employee_id'] == employee_id:
                # preserve all fields and types (convert scores to float already done)
                return dict(r)
        return {}  # Not found

    elif report_type == 'department' and employee_id is None:
        from collections import defaultdict
        groups = defaultdict(list)
        # Group rows by department
        for r in rows:
            groups[r['department']].append(r)
        result = {}
        for dept, group in groups.items():
            ratings = [g['overall_rating'] for g in group]
            count = len(ratings)
            avg = sum(ratings) / count if count else 0.0
            result[dept] = {
                'avg_rating': round(avg, 2),
                'count': count
            }
        return result

    else:
        # Invalid call/parameters
        return {}

